    $cancelSource=Join-Path $root 'cancel-source';$cancelTarget=Join-Path $root 'cancel-target';$cancelState=Join-Path $root 'cancel-state';[void][IO.Directory]::CreateDirectory($cancelSource);[void][IO.Directory]::CreateDirectory($cancelTarget);[void][IO.Directory]::CreateDirectory($cancelState)
    $cancelFile=Join-Path $cancelSource 'retry.txt';[IO.File]::WriteAllText($cancelFile,'safe retry payload',[Text.Encoding]::UTF8);$cancelItem=('b'*64);$cancelPlanPath=Join-Path $root 'cancel-plan.json'
    $cancelFixture=NewFixturePlan $cancelFile (Join-Path $cancelTarget 'retry.txt') $cancelSource $cancelTarget $pairId $cancelItem $cancelPlanPath
    $cancelFixture.Plan.TargetStateDirectory=Get-WsmPhysicalPath $cancelState;$cancelFixture.Plan.TargetStateDirectoryAccessPath=[IO.Path]::GetFullPath($cancelState);$cancelFixture.Plan.TargetStateDirectoryIdentity=$cancelFixture.Plan.TargetPhysicalProof.ObserverMachineFingerprint.ToLowerInvariant()+'|'+$cancelFixture.Plan.TargetStateDirectory.ToLowerInvariant();$cancelFixture.Plan.TargetStateDirectoryProofHash=Get-WsmHashText ($cancelFixture.Plan.TargetStateDirectoryIdentity+'|'+$cancelFixture.Plan.TargetStateDirectoryAccessPath.ToLowerInvariant()+'|');Write-WsmJson $cancelPlanPath $cancelFixture.Plan;$cancelFixture.Hash=Get-WsmAssistiveNonCHash $cancelPlanPath
    $cancelToken=New-WsmCancellationToken $pairId $cancelFixture.Plan.SealedPlanHash $cancelFixture.Plan.ManifestHash ([Guid]::NewGuid().ToString()) $cancelState;[void](Request-WsmCancellation $cancelToken 'fixture owner' 'cancel before next durable entry boundary')
    $cancelRun=Invoke-WsmAssistiveNonCTransferCore -TransferPlanPath $cancelPlanPath -ExpectedPlanHash $cancelFixture.Hash -JournalPath (Join-Path $root 'cancel-journal.json') -ResultPath (Join-Path $root 'cancel-result.json') -CancellationToken $cancelToken
    Check ($cancelRun.Result.Rows[0].Status -eq 'DeferredManual' -and $cancelRun.JournalRevision -gt 0 -and -not [IO.File]::Exists((Join-Path $cancelTarget 'retry.txt'))) 'Cancellation did not leave a durable deferred row before destination writes.'
    $retryToken=New-WsmCancellationToken $pairId $cancelFixture.Plan.SealedPlanHash $cancelFixture.Plan.ManifestHash ([Guid]::NewGuid().ToString()) $cancelState
    $retryRun=Invoke-WsmAssistiveNonCTransferCore -TransferPlanPath $cancelPlanPath -ExpectedPlanHash $cancelFixture.Hash -JournalPath (Join-Path $root 'cancel-journal.json') -ResultPath (Join-Path $root 'cancel-retry-result.json') -CancellationToken $retryToken
    Check ($retryRun.Result.Rows[0].Status -eq 'Applied' -and (Get-WsmAssistiveNonCHash (Join-Path $cancelTarget 'retry.txt')) -ceq (Get-WsmAssistiveNonCHash $cancelFile)) 'A fresh, correctly bound cancellation token could not safely resume the durable journal.'
    [IO.File]::WriteAllText((Join-Path $targetRoot 'site-content.txt'),'external drift')
    Reject {Reserve-WsmAssistiveNonCScope ($targetRoot+'-state') $valid.Plan $valid.Plan.Entries[0] $targetRoot} 'Existing reservation accepted destination content changed after its durable readback.'
    Check ($passed -ge 12) 'Expected transfer, metadata, resume, conflict, proof, registry and source-scope checks did not run.'
    Write-Host ('PASS: '+$passed+' Assistive non-C transfer checks.')
} finally {Remove-Item -LiteralPath $root -Recurse -Force -ErrorAction SilentlyContinue}
